<script setup>
import {ref,onMounted} from 'vue';import {api} from '../lib/api';import StateBox from '../components/StateBox.vue';
const rows=ref([]),loading=ref(true),error=ref(''),search=ref(''),page=ref(1),total=ref(0);
async function load(){loading.value=true;error.value='';try{const r=await api.get('/competitions',{params:{search:search.value,page:page.value,per_page:20}});rows.value=r.data;total.value=r.meta.total;}catch(e){error.value=e.message;}finally{loading.value=false;}}
onMounted(load);
</script>
<template><div class="heading"><div><p class="eyebrow">CATÁLOGO OFICIAL</p><h1>Competiciones</h1><p class="sub">Ligas y copas disponibles con la credencial autorizada.</p></div><span class="metric">{{total}} competiciones</span></div><div class="toolbar"><input v-model="search" @keyup.enter="page=1;load()" placeholder="Buscar competición…"/><button class="btn" @click="page=1;load()">Buscar</button><button class="btn muted" @click="load">↻ Actualizar</button></div><StateBox :loading="loading" :error="error" :empty="!rows.length" empty-text="El catálogo está vacío o sincronizándose. Comprueba el worker de importación."/><div class="cards" v-if="!loading&&!error"><RouterLink v-for="c in rows" :key="c.id" :to="'/competitions/'+c.id" class="competition-card"><img v-if="c.emblem" :src="c.emblem" alt=""/><span v-else class="glyph">🏆</span><span><strong>{{c.name}}</strong><small>{{c.type}} · {{c.code||'Sin código'}}</small></span><span class="pill" :class="c.snapshot_id?'good':''">{{c.snapshot_id?'Publicada':'No importada'}}</span><span class="arrow">→</span></RouterLink></div><div class="pager" v-if="total>20"><button class="btn muted" :disabled="page<=1" @click="page--;load()">Anterior</button><span>Página {{page}}</span><button class="btn muted" :disabled="page*20>=total" @click="page++;load()">Siguiente</button></div></template>
